"use client";

export default function ModalBasic({ open, onClose, title, children }) {
  if (!open) return null;

  return (
    <>
      <div className="ijent-modal-overlay" onClick={onClose}>
        <div
          className="ijent-modal-box"
          onClick={(e) => e.stopPropagation()}
        >
          <h3 className="ijent-modal-title">{title}</h3>

          <div className="ijent-modal-content">
            {children}
          </div>

          <button className="ijent-modal-btn" onClick={onClose}>
            Close
          </button>
        </div>
      </div>

      {/* CSS DI DALAM COMPONENT */}
      <style>{`
        .ijent-modal-overlay {
          position: fixed;
          inset: 0;
          background: rgba(0,0,0,0.45);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 999;
        }

        .ijent-modal-box {
          background: #ffffff;
          padding: 24px;
          border-radius: 10px;
          width: 360px;
          box-shadow: 0 10px 25px rgba(0,0,0,0.15);
        }

        .ijent-modal-title {
          margin-bottom: 12px;
          font-size: 18px;
          font-weight: 600;
        }

        .ijent-modal-content {
          margin-bottom: 20px;
          color: #374151;
        }

        .ijent-modal-btn {
          background: #0ea5e9;
          color: white;
          border: none;
          padding: 8px 16px;
          border-radius: 6px;
          cursor: pointer;
        }

        .ijent-modal-btn:hover {
          opacity: 0.9;
        }
      `}</style>
    </>
  );
}
