export default function CardImage({ image, title, location }) {
  const card = {
    border: '1px solid #e5e7eb',
    borderRadius: '12px',
    overflow: 'hidden',
    width: 240,
    background: '#ffffff',
  };

  return (
    <div style={card}>
      <img
        src={image}
        alt={title}
        style={{ width: '100%', height: 140, objectFit: 'cover' }}
      />

      <div style={{ padding: 16 }}>
        <h4>{title}</h4>
        <p style={{ fontSize: 13, color: '#6b7280' }}>{location}</p>
      </div>
    </div>
  );
}
