"use client";

export default function ModalFullscreen({ open, onClose, children }) {
  if (!open) return null;

  return (
    <>
      <div className="ijent-modal-full">
        <button
          className="ijent-modal-close"
          onClick={onClose}
        >
          ✕
        </button>

        {children}
      </div>

      <style>{`
        .ijent-modal-full {
          position: fixed;
          inset: 0;
          background: #fff;
          padding: 40px;
          z-index: 999;
          overflow-y: auto;
        }

        .ijent-modal-close {
          position: fixed;
          top: 20px;
          right: 20px;
          border: none;
          background: transparent;
          font-size: 22px;
          cursor: pointer;
        }
      `}</style>
    </>
  );
}
