"use client";

export default function ModalConfirm({
  open,
  title = "Confirmation",
  message,
  onConfirm,
  onClose,
}) {
  if (!open) return null;

  return (
    <>
      <div className="ijent-modal-overlay" onClick={onClose}>
        <div
          className="ijent-modal-box"
          onClick={(e) => e.stopPropagation()}
        >
          <h3 className="ijent-modal-title">{title}</h3>
          <p className="ijent-modal-text">{message}</p>

          <div className="ijent-modal-actions">
            <button
              className="ijent-btn secondary"
              onClick={onClose}
            >
              Cancel
            </button>
            <button
              className="ijent-btn danger"
              onClick={onConfirm}
            >
              Confirm
            </button>
          </div>
        </div>
      </div>

      <style>{`
        .ijent-modal-overlay {
          position: fixed;
          inset: 0;
          background: rgba(0,0,0,.45);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 999;
        }

        .ijent-modal-box {
          background: #fff;
          padding: 24px;
          border-radius: 10px;
          width: 360px;
        }

        .ijent-modal-title {
          margin-bottom: 12px;
          font-size: 18px;
        }

        .ijent-modal-text {
          color: #374151;
          margin-bottom: 20px;
        }

        .ijent-modal-actions {
          display: flex;
          justify-content: flex-end;
          gap: 10px;
        }

        .ijent-btn {
          padding: 8px 14px;
          border-radius: 6px;
          border: none;
          cursor: pointer;
        }

        .ijent-btn.secondary {
          background: #e5e7eb;
        }

        .ijent-btn.danger {
          background: #ef4444;
          color: white;
        }
      `}</style>
    </>
  );
}
