"use client";

export default function PlaceholderImage({ width = 200, height = 120 }) {
    return (
        <div
            style={{
                width,
                height,
                background: "#e5e7eb",
                borderRadius: 6,
                animation: "pulse 1.5s infinite",
            }}
        >
            <style jsx>{`
                @keyframes pulse {
                    0% { opacity: 1; }
                    50% { opacity: 0.4; }
                    100% { opacity: 1; }
                }
            `}</style>
        </div>
    );
}
