"use client";
import { useState } from "react";

export default function DropdownSplit({ label, items = [] }) {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ display: "flex", position: "relative" }}>
      <button style={mainBtn}>{label}</button>
      <button style={arrowBtn} onClick={() => setOpen(!open)}>
        ▼
      </button>

      {open && (
        <div style={menu}>
          {items.map((item, i) => (
            <div key={i} style={itemStyle}>{item}</div>
          ))}
        </div>
      )}
    </div>
  );
}

const mainBtn = {
  padding: "8px 12px",
  background: "#2563eb",
  color: "#ffffff",
  border: "none",
  borderRadius: "6px 0 0 6px"
};

const arrowBtn = {
  padding: "8px 12px",
  background: "#1e40af",
  color: "#ffffff",
  border: "none",
  borderRadius: "0 6px 6px 0",
  cursor: "pointer"
};

const menu = {
  position: "absolute",
  top: "110%",
  right: 0,
  width: 200,
  background: "#eff6ff",
  borderRadius: 6,
  border: "1px solid #2563eb"
};

const itemStyle = {
  padding: "8px 12px",
  cursor: "pointer",
  color: "#1e3a8a",
  fontWeight: 500
};

