"use client";

export default function PlaceholderCard() {
    return (
        <div
            style={{
                border: "1px solid #e5e7eb",
                borderRadius: 8,
                padding: 16,
                width: 240,
            }}
        >
            <div
                style={{
                    height: 120,
                    background: "#e5e7eb",
                    borderRadius: 6,
                    marginBottom: 12,
                    animation: "pulse 1.5s infinite",
                }}
            />
            <div
                style={{
                    height: 14,
                    width: "70%",
                    background: "#e5e7eb",
                    marginBottom: 8,
                }}
            />
            <div
                style={{
                    height: 12,
                    width: "90%",
                    background: "#e5e7eb",
                }}
            />

            <style jsx>{`
                @keyframes pulse {
                    0% { opacity: 1; }
                    50% { opacity: 0.4; }
                    100% { opacity: 1; }
                }
            `}</style>
        </div>
    );
}
