export default function CardBasic({ title, description }) {
  const card = {
    border: '1px solid #e5e7eb',
    borderRadius: '10px',
    padding: '20px',
    background: '#ffffff',
  };

  return (
    <div style={card}>
      <h3 style={{ marginBottom: 8 }}>{title}</h3>
      <p style={{ color: '#6b7280', fontSize: 14 }}>
        {description}
      </p>
    </div>
  );
}
