export default function ButtonInfo({ children }) {
  const style = {
    padding: '8px 16px',
    borderRadius: '6px',
    border: 'none',
    backgroundColor: '#06b6d4', // cyan / info
    color: '#ffffff',
    fontSize: '14px',
    cursor: 'pointer',
    transition: 'background-color 0.2s ease',
  };

  return (
    <button
      style={style}
      onMouseOver={(e) => e.target.style.backgroundColor = '#0891b2'}
      onMouseOut={(e) => e.target.style.backgroundColor = '#06b6d4'}
    >
      {children}
    </button>
  );
}
