export default function CardPrice({ title, price, features }) {
  const card = {
    border: '1px solid #e5e7eb',
    borderRadius: 12,
    padding: 24,
    width: 260,
    background: '#ffffff',
  };

  return (
    <div style={card}>
      <h3>{title}</h3>
      <p style={{ fontSize: 24, fontWeight: 'bold', margin: '10px 0' }}>
        Rp {price}
      </p>

      <ul style={{ paddingLeft: 18, fontSize: 14, color: '#6b7280' }}>
        {features.map((f, i) => (
          <li key={i}>{f}</li>
        ))}
      </ul>
    </div>
  );
}
