"use client";

export default function ModalImage({ open, image, onClose }) {
  if (!open) return null;

  return (
    <>
      <div className="ijent-modal-overlay" onClick={onClose}>
        <div className="ijent-modal-image">
          <img src={image} alt="Preview" />
        </div>
      </div>

      <style>{`
        .ijent-modal-overlay {
          position: fixed;
          inset: 0;
          background: rgba(0,0,0,.6);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 999;
        }

        .ijent-modal-image img {
          max-width: 90vw;
          max-height: 80vh;
          border-radius: 10px;
          box-shadow: 0 20px 40px rgba(0,0,0,.4);
        }
      `}</style>
    </>
  );
}
