"use client";
import { useState } from "react";

export default function DropdownBasic({ label = "Dropdown", items = [] }) {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ position: "relative", width: 200 }}>
      <button
        onClick={() => setOpen(!open)}
        style={btn}
      >
        {label}
      </button>

      {open && (
        <div style={menu}>
          {items.map((item, i) => (
            <div key={i} style={itemStyle}>{item}</div>
          ))}
        </div>
      )}
    </div>
  );
}

const btn = {
  width: "100%",
  padding: "8px 12px",
  borderRadius: 6,
  border: "1px solid #e5e7eb",
  background: "#ffffff",
  cursor: "pointer"
};

const menu = {
  position: "absolute",
  top: "110%",
  width: "100%",
  background: "#ffffff",
  border: "1px solid #e5e7eb",
  borderRadius: 6,
  boxShadow: "0 8px 20px rgba(0,0,0,.08)"
};

const itemStyle = {
  padding: "8px 12px",
  cursor: "pointer",
  color: "#1e3a8a",        // biru gelap
  fontWeight: 500
};

