"use client";
import { useState } from "react";

export default function DropdownDark({ label, items = [] }) {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ position: "relative", width: 200 }}>
      <button style={btn} onClick={() => setOpen(!open)}>
        {label}
      </button>

      {open && (
        <div style={menu}>
          {items.map((item, i) => (
            <div key={i} style={itemStyle}>{item}</div>
          ))}
        </div>
      )}
    </div>
  );
}

const btn = {
  padding: "8px 12px",
  width: "100%",
  background: "#111827",
  color: "#ffffff",
  borderRadius: 6,
  border: "none",
  cursor: "pointer"
};

const menu = {
  position: "absolute",
  top: "110%",
  width: "100%",
  background: "#1f2933",
  borderRadius: 6,
  color: "#ffffff"
};

const itemStyle = {
  padding: "8px 12px"
};
