export default function CardIcon({ icon, title, text }) {
  const card = {
    border: '1px solid #e5e7eb',
    borderRadius: '10px',
    padding: 20,
    textAlign: 'center',
    background: '#ffffff',
    width: 200,
  };

  return (
    <div style={card}>
      <div style={{ fontSize: 32, marginBottom: 10 }}>{icon}</div>
      <h4>{title}</h4>
      <p style={{ fontSize: 13, color: '#6b7280' }}>{text}</p>
    </div>
  );
}
