"use client";
import { useState } from "react";

export default function DropdownIcon({ label, icon = "⚙️", items = [] }) {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ position: "relative", width: 200 }}>
      <button onClick={() => setOpen(!open)} style={btn}>
        <span>{icon}</span>
        <span>{label}</span>
      </button>

      {open && (
        <div style={menu}>
          {items.map((item, i) => (
            <div key={i} style={itemStyle}>{item}</div>
          ))}
        </div>
      )}
    </div>
  );
}

const btn = {
  display: "flex",
  gap: 8,
  alignItems: "center",
  padding: "8px 12px",
  width: "100%",
  borderRadius: 6,
  border: "1px solid #e5e7eb",
  background: "#ffffff",
  cursor: "pointer"
};

const menu = {
  position: "absolute",
  top: "110%",
  width: "100%",
  background: "#ffffff",
  borderRadius: 6,
  border: "1px solid #e5e7eb"
};

const itemStyle = {
  padding: "8px 12px",
  cursor: "pointer",
  color: "#1e3a8a",
  fontWeight: 500
};
