"use client";
import { useState } from "react";

export default function DropdownOutline({ label, items = [] }) {
  const [open, setOpen] = useState(false);

  return (
    <div style={{ position: "relative", width: 200 }}>
      <button style={btn} onClick={() => setOpen(!open)}>
        {label}
      </button>

      {open && (
        <div style={menu}>
          {items.map((item, i) => (
            <div key={i} style={itemStyle}>{item}</div>
          ))}
        </div>
      )}
    </div>
  );
}

const btn = {
  padding: "8px 12px",
  width: "100%",
  background: "#facc15",
  border: "none",
  borderRadius: 6,
  color: "#1f2933",
  cursor: "pointer",
  fontWeight: 500
};

const menu = {
  position: "absolute",
  top: "110%",
  width: "100%",
  background: "#fef9c3",
  borderRadius: 6,
  border: "1px solid #eab308"
};

const itemStyle = {
  padding: "8px 12px",
  cursor: "pointer",
  color: "#92400e",      // coklat gelap (kontras kuning)
  fontWeight: 600
};
