export default function CardProfile({ avatar, name, role }) {
  const card = {
    border: '1px solid #e5e7eb',
    borderRadius: '12px',
    padding: 20,
    width: 220,
    textAlign: 'center',
    background: '#ffffff',
  };

  return (
    <div style={card}>
      <img
        src={avatar}
        alt={name}
        style={{
          width: 80,
          height: 80,
          borderRadius: '50%',
          objectFit: 'cover',
          marginBottom: 12
        }}
      />

      <h4>{name}</h4>
      <p style={{ fontSize: 13, color: '#6b7280' }}>{role}</p>
    </div>
  );
}
