"use client";

export default function PlaceholderText({ lines = 3 }) {
    return (
        <div>
            {[...Array(lines)].map((_, i) => (
                <div
                    key={i}
                    style={{
                        height: 12,
                        width: `${100 - i * 10}%`,
                        background: "#e5e7eb",
                        borderRadius: 4,
                        marginBottom: 8,
                        animation: "pulse 1.5s infinite",
                    }}
                />
            ))}

            <style jsx>{`
                @keyframes pulse {
                    0% { opacity: 1; }
                    50% { opacity: 0.4; }
                    100% { opacity: 1; }
                }
            `}</style>
        </div>
    );
}
