export default function ButtonSuccess({ children }) {
  const style = {
    padding: '8px 16px',
    borderRadius: '6px',
    border: 'none',
    backgroundColor: '#16a34a', // green
    color: '#ffffff',
    fontSize: '14px',
    cursor: 'pointer',
    transition: 'background-color 0.2s ease',
  };

  return (
    <button
      style={style}
      onMouseOver={(e) => e.target.style.backgroundColor = '#15803d'}
      onMouseOut={(e) => e.target.style.backgroundColor = '#16a34a'}
    >
      {children}
    </button>
  );
}
