"use client";

export default function PlaceholderAvatar({ size = 48 }) {
    return (
        <div
            style={{
                width: size,
                height: size,
                borderRadius: "50%",
                background: "#e5e7eb",
                animation: "pulse 1.5s infinite",
            }}
        >
            <style jsx>{`
                @keyframes pulse {
                    0% { opacity: 1; }
                    50% { opacity: 0.4; }
                    100% { opacity: 1; }
                }
            `}</style>
        </div>
    );
}
