"use client";

export default function ModalForm({ open, onClose, onSubmit }) {
  if (!open) return null;

  return (
    <>
      <div className="ijent-modal-overlay" onClick={onClose}>
        <div
          className="ijent-modal-box"
          onClick={(e) => e.stopPropagation()}
        >
          <h3 className="ijent-modal-title">Contact Admin</h3>

          <input className="ijent-input" placeholder="Name" />
          <input className="ijent-input" placeholder="Email" />
          <textarea
            className="ijent-input"
            placeholder="Message"
          />

          <button
            className="ijent-btn primary"
            onClick={onSubmit}
          >
            Submit
          </button>
        </div>
      </div>

      <style>{`
        .ijent-modal-overlay {
          position: fixed;
          inset: 0;
          background: rgba(0,0,0,.45);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 999;
        }

        .ijent-modal-box {
          background: #fff;
          padding: 24px;
          border-radius: 10px;
          width: 380px;
        }

        .ijent-input {
          width: 100%;
          padding: 8px;
          margin-bottom: 10px;
          border-radius: 6px;
          border: 1px solid #d1d5db;
        }

        .ijent-btn.primary {
          background: #0ea5e9;
          color: white;
          border: none;
          padding: 8px 14px;
          border-radius: 6px;
        }
      `}</style>
    </>
  );
}
