"use client";

export default function PlaceholderButton({ width = 100 }) {
    return (
        <div
            style={{
                height: 36,
                width,
                borderRadius: 6,
                background: "#e5e7eb",
                animation: "pulse 1.5s infinite",
            }}
        >
            <style jsx>{`
                @keyframes pulse {
                    0% { opacity: 1; }
                    50% { opacity: 0.4; }
                    100% { opacity: 1; }
                }
            `}</style>
        </div>
    );
}
